// Runs the Sail $[test] functions (sail-riscv test/unit_tests/main_unit_tests.cpp).
// usage: unit_tests <config.json>
#include <stdio.h>
#include "sail.h"
#include "sail_config.h"
#include "tsp_config_check.h"
#include "tsp_config_schema.h"

// Generated by Sail: runs every $[test] function, each between model_init/model_fini.
extern void model_test(void);
extern void model_init(void);
extern void model_fini(void);

int main(int argc, char **argv) {
  if (argc != 2) {
    fprintf(stderr, "usage: %s <config.json>\n", argv[0]);
    return 2;
  }
  // The same configuration check as tsp_sim: exit 2 naming the key.
  tsp_config_load("unit_tests", argv[1], TSP_CONFIG_SCHEMA);
  model_init();
  tsp_config_model_check("unit_tests", argv[1]);
  model_fini();
  model_test();
  printf("unit tests passed (%s)\n", argv[1]);
  return 0;
}
